@startuml

class Product {
  + name : string
  + description : string
  + netPrice : double
}

class Company {
  + name : string
}

class Country {
  + name : string
  + vatRate : double
  + currency : string
  + conversionRateToEuro : double
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephoneNumber : string
  + emailAddress : string
}

class Customer {
  + name : string
  + address : string
  + telephoneNumber : string
  + emailAddress : string
}

class Order {
  + orderID : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

Product "*" -- "1" Company : manufacturedBy
Product "*" -- "1" Country : soldIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "0..*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product : refersTo
Order "*" -- "1" Customer : placedBy

@enduml

